#!/usr/bin/env bash
set -euo pipefail
ROOT=/work;BUILD="$ROOT/build";TOOL="${MOS_TOOLCHAIN:-$BUILD/llvm-mos-install}/bin";CFG="$BUILD/install/bin/mos-snes-hirom.cfg";SRC="$ROOT/examples/snes/bankwalk.c";ASM="$BUILD/bankwalk-table.s";VENDOR="$ROOT/vendor/bsnes-jg";A16=(-Xclang -target-feature -Xclang +mos-a16);XY16=(-Xclang -target-feature -Xclang +mos-a16 -Xclang -target-feature -Xclang +mos-xy16)
cc -DHOST -O2 "$ROOT/tools/bankwalk-sim.c" -o "$BUILD/bankwalk-sim";EXPECT=$("$BUILD/bankwalk-sim"|grep -oE '0x[0-9A-Fa-f]{4}'|head -1);python3 "$ROOT/tools/gen-bankwalk-asm.py" "$ASM";echo "==> host oracle: $EXPECT"
for mode in a16 xy16;do feat=("${A16[@]}");[ "$mode" = xy16 ]&&feat=("${XY16[@]}");"$TOOL/mos-clang" --config "$CFG" -mcpu=mosw65816 "${feat[@]}" -Os -mllvm -verify-machineinstrs -Wl,-Map="$BUILD/bankwalk-$mode.map" -o "$BUILD/bankwalk-$mode.sfc" "$SRC" "$ASM";python3 "$ROOT/tools/snes-checksum.py" --hirom "$BUILD/bankwalk-$mode.sfc">/dev/null;done
"$TOOL/mos-clang" --config "$CFG" -mcpu=mosw65816 "${A16[@]}" -Os -fno-lto -mllvm -verify-machineinstrs -c "$SRC" -o "$BUILD/bankwalk.o";dis=$("$TOOL/llvm-objdump" -dr --mcpu=mosw65816 "$BUILD/bankwalk.o");grep -qE 'lda.*\[' <<<"$dis"||{ echo 'FAIL: no far load';exit 1;};echo '    PASS: far loads + 24-bit pointer arithmetic verify'
rc=0;export SMOKE_SETTLE=480;export SMOKE_SECONDS=12;source "$ROOT/dev/_emu.sh";require_bios||exit $?;for mode in a16 xy16;do run_assert "$BUILD/bankwalk-$mode.sfc" "$BUILD/bankwalk-$mode.map" corpus_result "$EXPECT"||rc=1;VMA=$(awk '$NF=="corpus_result"{print $1;exit}' "$BUILD/bankwalk-$mode.map");"$BUILD/jgxcheck" "$BUILD/bankwalk-$mode.sfc" "$VENDOR/Database" "0x$VMA" 2 "$EXPECT" 480 "$BUILD/bankwalk-$mode-jg.png"||rc=1;done;[ "$rc" = 0 ]&&echo "RESULT: PASS — BankWalk host == a16 == xy16 == $EXPECT"||echo FAIL;exit "$rc"
